# BEFORE (persistent kernel — faster)
@triton.jit
def kernel(...):
    sm_id = tl.program_id(0)
    tile_id = sm_id
    while tile_id < num_tiles:
        pid_m, pid_n = swizzle(tile_id)
        acc = matmul_tile(A, B, pid_m, pid_n)
        store(out, acc + bias)
        tile_id += NUM_SMS  # persistent loop

